import React, { useState, useEffect } from 'react';

function AdminDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [stats, setStats] = useState({ users: {}, services: {}, bookings: {}, revenue: {} });
  const [users, setUsers] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [services, setServices] = useState([]);
  const [analytics, setAnalytics] = useState({ weeklyBookings: [], monthlyRevenue: [] });
  const [loading, setLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState(null);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      // Fetch stats
      const statsRes = await fetch('http://localhost:5000/api/admin/stats', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const statsData = await statsRes.json();
      if (statsData.success) setStats(statsData.stats);

      // Fetch users
      const usersRes = await fetch('http://localhost:5000/api/admin/users', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const usersData = await usersRes.json();
      if (usersData.success) setUsers(usersData.users);

      // Fetch bookings
      const bookingsRes = await fetch('http://localhost:5000/api/admin/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const bookingsData = await bookingsRes.json();
      if (bookingsData.success) setBookings(bookingsData.bookings);

      // Fetch services
      const servicesRes = await fetch('http://localhost:5000/api/admin/services', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const servicesData = await servicesRes.json();
      if (servicesData.success) setServices(servicesData.services);

      // Fetch analytics
      const analyticsRes = await fetch('http://localhost:5000/api/admin/analytics', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const analyticsData = await analyticsRes.json();
      if (analyticsData.success) setAnalytics(analyticsData.analytics);
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateUserStatus = async (userId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isActive })
      });
      const data = await res.json();
      if (data.success) {
        alert(`User ${isActive ? 'activated' : 'suspended'}!`);
        fetchAllData();
      }
    } catch (error) {
      alert('Failed to update user');
    }
  };

  const toggleServiceStatus = async (serviceId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/services/${serviceId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isActive: !isActive })
      });
      const data = await res.json();
      if (data.success) {
        alert(`Service ${!isActive ? 'activated' : 'deactivated'}!`);
        fetchAllData();
      }
    } catch (error) {
      alert('Failed to update service');
    }
  };

  const getRoleBadge = (role) => {
    const colors = {
      customer: { bg: '#d1fae5', color: '#065f46', icon: '👤' },
      provider: { bg: '#e0e7ff', color: '#4338ca', icon: '🔧' },
      driver: { bg: '#fef3c7', color: '#92400e', icon: '🚗' },
      admin: { bg: '#f3e8ff', color: '#7c3aed', icon: '👑' }
    };
    const c = colors[role] || { bg: '#f3f4f6', color: '#6b7280', icon: '❓' };
    return <span style={{ backgroundColor: c.bg, color: c.color, padding: '4px 8px', borderRadius: '20px', fontSize: '12px' }}>{c.icon} {role}</span>;
  };

  return (
    <div style={styles.dashboard}>
      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>👑</span>
          <h1 style={styles.logoText}>Car Care Connect - Admin</h1>
        </div>
        <div style={styles.userInfo}>
          <span>👑 {user.firstName} {user.lastName}</span>
          <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
        </div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'users' ? styles.activeTab : {})}} onClick={() => setActiveTab('users')}>👥 Users ({stats.users?.total || 0})</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings ({stats.bookings?.total || 0})</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => setActiveTab('services')}>🔧 Services ({stats.services?.total || 0})</button>
        <button style={{...styles.tab, ...(activeTab === 'analytics' ? styles.activeTab : {})}} onClick={() => setActiveTab('analytics')}>📈 Analytics</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? (
          <div style={styles.loading}>Loading platform data...</div>
        ) : (
          <>
            {/* Dashboard Tab - Stats Overview */}
            {activeTab === 'dashboard' && (
              <div>
                <div style={styles.statsGrid}>
                  <div style={styles.statCard}>
                    <span style={styles.statIcon}>👥</span>
                    <h3>Total Users</h3>
                    <p style={styles.statNumber}>{stats.users?.total || 0}</p>
                    <div style={styles.statBreakdown}>
                      <span>👤 {stats.users?.customers || 0}</span>
                      <span>🔧 {stats.users?.providers || 0}</span>
                      <span>🚗 {stats.users?.drivers || 0}</span>
                    </div>
                  </div>
                  <div style={styles.statCard}>
                    <span style={styles.statIcon}>📅</span>
                    <h3>Bookings</h3>
                    <p style={styles.statNumber}>{stats.bookings?.total || 0}</p>
                    <div style={styles.statBreakdown}>
                      <span style={{ color: '#10b981' }}>✓ {stats.bookings?.completed || 0}</span>
                      <span style={{ color: '#f59e0b' }}>⏳ {stats.bookings?.pending || 0}</span>
                    </div>
                  </div>
                  <div style={styles.statCard}>
                    <span style={styles.statIcon}>💰</span>
                    <h3>Revenue</h3>
                    <p style={styles.statNumber}>${stats.revenue?.total?.toLocaleString() || 0}</p>
                    <div style={styles.statBreakdown}>
                      <span>Commission: ${stats.revenue?.platformCommission?.toLocaleString() || 0}</span>
                    </div>
                  </div>
                  <div style={styles.statCard}>
                    <span style={styles.statIcon}>🔧</span>
                    <h3>Services</h3>
                    <p style={styles.statNumber}>{stats.services?.total || 0}</p>
                  </div>
                </div>

                {/* Recent Activity */}
                <div style={styles.card}>
                  <h3>📋 Recent Activity</h3>
                  <div style={styles.activityList}>
                    {bookings.slice(0, 5).map(booking => (
                      <div key={booking._id} style={styles.activityItem}>
                        <span>📅 New booking: {booking.serviceName} by {booking.customerId?.firstName}</span>
                        <span style={styles.activityTime}>{new Date(booking.createdAt).toLocaleDateString()}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Users Tab - Complete User Management */}
            {activeTab === 'users' && (
              <div>
                <h2>👥 User Management</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr>
                    </thead>
                    <tbody>
                      {users.map(u => (
                        <tr key={u._id}>
                          <td><strong>{u.firstName} {u.lastName}</strong></td>
                          <td>{u.email}</td>
                          <td>{getRoleBadge(u.role)}</td>
                          <td><span style={{ color: u.isActive ? '#10b981' : '#ef4444' }}>{u.isActive ? 'Active' : 'Suspended'}</span></td>
                          <td>{new Date(u.createdAt).toLocaleDateString()}</td>
                          <td>
                            <button style={{...styles.actionBtn, backgroundColor: u.isActive ? '#ef4444' : '#10b981'}} onClick={() => updateUserStatus(u._id, !u.isActive)}>
                              {u.isActive ? 'Suspend' : 'Activate'}
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Bookings Tab */}
            {activeTab === 'bookings' && (
              <div>
                <h2>📅 All Bookings</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>Service</th><th>Customer</th><th>Provider</th><th>Date</th><th>Amount</th><th>Status</th></tr>
                    </thead>
                    <tbody>
                      {bookings.map(b => (
                        <tr key={b._id}>
                          <td>{b.serviceName}</td>
                          <td>{b.customerId?.firstName} {b.customerId?.lastName}</td>
                          <td>{b.providerId?.businessName || b.providerId?.firstName}</td>
                          <td>{new Date(b.bookingDate).toLocaleDateString()}</td>
                          <td>${b.totalAmount}</td>
                          <td><span style={{ backgroundColor: b.status === 'completed' ? '#d1fae5' : '#fef3c7', padding: '4px 8px', borderRadius: '20px', fontSize: '12px' }}>{b.status}</span></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Services Tab */}
            {activeTab === 'services' && (
              <div>
                <h2>🔧 All Services</h2>
                <div style={styles.tableContainer}>
                  <table style={styles.table}>
                    <thead>
                      <tr><th>Name</th><th>Provider</th><th>Category</th><th>Price</th><th>Status</th><th>Actions</th></tr>
                    </thead>
                    <tbody>
                      {services.map(s => (
                        <tr key={s._id}>
                          <td>{s.name}</td>
                          <td>{s.providerId?.businessName || s.providerId?.firstName}</td>
                          <td>{s.category}</td>
                          <td>${s.price}</td>
                          <td><span style={{ color: s.isActive ? '#10b981' : '#ef4444' }}>{s.isActive ? 'Active' : 'Hidden'}</span></td>
                          <td>
                            <button style={styles.actionBtn} onClick={() => toggleServiceStatus(s._id, s.isActive)}>
                              {s.isActive ? 'Hide' : 'Show'}
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Analytics Tab */}
            {activeTab === 'analytics' && (
              <div>
                <h2>📈 Platform Analytics</h2>
                <div style={styles.statsGrid}>
                  <div style={styles.statCard}>
                    <h3>Weekly Bookings</h3>
                    {analytics.weeklyBookings?.map((week, i) => (
                      <div key={i} style={{ margin: '10px 0' }}>
                        <span>{week.date}</span>
                        <div style={{ backgroundColor: '#e5e7eb', borderRadius: '10px', marginTop: '5px' }}>
                          <div style={{ width: `${(week.count / 20) * 100}%`, backgroundColor: '#3b82f6', padding: '5px', borderRadius: '10px', color: 'white', textAlign: 'center' }}>
                            {week.count} bookings
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                  <div style={styles.statCard}>
                    <h3>Monthly Revenue</h3>
                    {analytics.monthlyRevenue?.map((month, i) => (
                      <div key={i} style={{ margin: '10px 0' }}>
                        <span>{month.month}</span>
                        <p><strong>${month.revenue?.toLocaleString() || 0}</strong></p>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

